<!doctype html><html><head><meta charset="utf-8"><style>body{font:11px Arial;color:#102a2a}h1{margin:0}table{width:100%;border-collapse:collapse;margin-top:18px}th{background:#d7f3ed;text-align:left}th,td{padding:7px;border-bottom:1px solid #d9e8e5}.amount{text-align:right}</style></head><body><h1>{{ $shop->name }} - Inventory Report</h1><p>Generated {{ now()->format('M d, Y g:i A') }}</p><table><tr><th>Product</th><th>SKU</th><th>Status</th><th class="amount">Stock</th><th class="amount">Average Cost</th></tr>@foreach($products as $product)@foreach($product->variants as $variant)@php($batches=$variant->inventories)@php($qty=$batches->sum('quantity'))<tr><td>{{ $product->name }}</td><td>{{ $variant->sku }}</td><td>{{ ucfirst($product->status) }}</td><td class="amount">{{ $qty }}</td><td class="amount">₱{{ number_format($batches->avg('cost_price') ?? 0,2) }}</td></tr>@endforeach@endforeach</table></body></html>
